import{_ as e,o as r,c as l,ai as i}from"./chunks/framework.Dt-5ltfC.js";const b=JSON.parse('{"title":"常见问题（安装版）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),t={name:"guide/faq.md"};function h(o,a,s,n,d,c){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="常见问题-安装版" tabindex="-1">常见问题（安装版） <a class="header-anchor" href="#常见问题-安装版" aria-label="Permalink to “常见问题（安装版）”">​</a></h1><h2 id="软件是免费的吗" tabindex="-1">软件是免费的吗？ <a class="header-anchor" href="#软件是免费的吗" aria-label="Permalink to “软件是免费的吗？”">​</a></h2><p>是。软件完全免费。若你通过第三方付费购买，请立即退款并从官方发布页重新下载。</p><h2 id="到哪里下载才是官方版本" tabindex="-1">到哪里下载才是官方版本？ <a class="header-anchor" href="#到哪里下载才是官方版本" aria-label="Permalink to “到哪里下载才是官方版本？”">​</a></h2><p>仅建议使用项目发布页：</p><ul><li><a href="https://github.com/hacker-frok/qq-farm-bot-ai/releases/latest" target="_blank" rel="noreferrer">https://github.com/hacker-frok/qq-farm-bot-ai/releases/latest</a></li></ul><h2 id="为什么启动后没反应或启动失败" tabindex="-1">为什么启动后没反应或启动失败？ <a class="header-anchor" href="#为什么启动后没反应或启动失败" aria-label="Permalink to “为什么启动后没反应或启动失败？”">​</a></h2><p>优先排查：</p><ol><li>是否为 Windows 10/11。</li><li>是否被安全软件拦截（安装程序、快捷方式或主程序）。</li><li>是否缺少 VC++ 运行库，可尝试安装： <a href="https://aka.ms/vc14/vc_redist.x64.exe" target="_blank" rel="noreferrer">https://aka.ms/vc14/vc_redist.x64.exe</a></li></ol><h2 id="微信平台为什么会影响我打字" tabindex="-1">微信平台为什么会影响我打字？ <a class="header-anchor" href="#微信平台为什么会影响我打字" aria-label="Permalink to “微信平台为什么会影响我打字？”">​</a></h2><p>微信小程序可能抢焦点，这是已知问题。建议：</p><ol><li>新建一个系统桌面运行机器人。</li><li>或在虚拟机中运行机器人。</li></ol><h2 id="虚拟机-云电脑运行不稳定怎么办" tabindex="-1">虚拟机/云电脑运行不稳定怎么办？ <a class="header-anchor" href="#虚拟机-云电脑运行不稳定怎么办" aria-label="Permalink to “虚拟机/云电脑运行不稳定怎么办？”">​</a></h2><ol><li>调大任务间隔，避免卡顿和弹窗漏检。</li><li>不要隐藏小程序窗口（虚拟环境下更容易异常）。</li><li>优先使用默认配置，再逐项微调。</li></ol><h2 id="为什么偶尔会停机或重启" tabindex="-1">为什么偶尔会停机或重启？ <a class="header-anchor" href="#为什么偶尔会停机或重启" aria-label="Permalink to “为什么偶尔会停机或重启？”">​</a></h2><p>程序包含稳定性保护机制，例如：</p><ul><li>“下次再来”/“重新连接”检测</li><li>周期重启策略</li><li>休息时段暂停</li></ul><p>这类行为通常是预期保护，不是单纯故障。</p><h2 id="如何安全升级版本" tabindex="-1">如何安全升级版本？ <a class="header-anchor" href="#如何安全升级版本" aria-label="Permalink to “如何安全升级版本？”">​</a></h2><ol><li>先关闭当前程序。</li><li>下载最新安装包并安装。</li><li>启动后先观察日志与关键功能（收获、播种、好友链路）是否正常。</li></ol><h2 id="去哪里反馈问题" tabindex="-1">去哪里反馈问题？ <a class="header-anchor" href="#去哪里反馈问题" aria-label="Permalink to “去哪里反馈问题？”">​</a></h2><ul><li>Telegram 群：<a href="https://t.me/qq_farm_bot_ai" target="_blank" rel="noreferrer">https://t.me/qq_farm_bot_ai</a></li><li>GitHub Issues：<a href="https://github.com/hacker-frok/qq-farm-bot-ai/issues" target="_blank" rel="noreferrer">https://github.com/hacker-frok/qq-farm-bot-ai/issues</a></li></ul><h2 id="免责声明" tabindex="-1">免责声明 <a class="header-anchor" href="#免责声明" aria-label="Permalink to “免责声明”">​</a></h2><p>本项目仅用于学习与研究计算机视觉自动化技术。使用本项目可能违反相关平台服务条款并带来账号风险，后果由使用者自行承担。</p>',24)])])}const m=e(t,[["render",h]]);export{b as __pageData,m as default};
